-- One-time import of the expanded native DeltaNet chunk operator. The source
-- artifact was generated by dnstep.sass with DN_CHUNK=1; no runtime dependency.
local f=assert(io.open(assert(arg[1]),"rb")); local s=f:read("a"); f:close()
local maps={}
for line in assert(s:match("<REGISTER_MAPPING>(.-)</REGISTER_MAPPING>")):gmatch("[^\n]+") do
  if line:find("dnstepc_",1,true) then maps[#maps+1]=line.."\n" end
end
assert(#maps>0)
local a=assert(s:find("\ndnstepc_SETUP:\n",1,true))
local b=assert(s:find("\n[%w_]+_SETUP:\n",a+2))
io.write("# Native DeltaNet chunk operator, imported from die_slab21.sass.\n<REGISTER_MAPPING>\n",table.concat(maps),"</REGISTER_MAPPING>\n",s:sub(a+1,b))
